SELECT sm.id AS master_id,sm.title,sm.track,sm.disc,sm.album_id,a.name AS album_name,si.id AS instance_id,si.suffix,si.storage_object_id,so.physical_key,so.etag,so.size,se.path,se.companion_of FROM song_masters sm JOIN song_instances si ON si.master_id=sm.id JOIN storage_objects so ON so.id=si.storage_object_id LEFT JOIN albums a ON a.id=sm.album_id LEFT JOIN storage_entries se ON se.instance_id=si.id AND se.kind='file' WHERE (a.id='al-9544935a62') OR sm.id IN ('sm-upload-33959ca1-297','sm-upload-34c51de9-aa4','sm-upload-637470c0-5af','sm-upload-64363012-149','sm-upload-66bdb06b-1cb','sm-upload-6b506d3e-f76','sm-upload-6c0a0dc9-c4a','sm-upload-89d8af71-0b6','sm-upload-8b4e6e46-206','sm-upload-95621150-291','sm-upload-b33cfb39-448','sm-upload-debc2a1c-66a') ORDER BY sm.album_id,sm.track,sm.id